int fib(int n)
{
    // Base case: the first two Fibonacci numbers are defined as 0 and 1.
    if (n <= 1)
        return n;

    // Recursive call with the next index; the loop invariant guarantees termination.
    for (int i = 2; i <= n; ++i) {
        auto a = fib(i - 1);
        auto b = fib(i - 2);
        fib(i) = a + b;
    }
    return fib(n);
}

int fib(int n)
{
    if (n <= 1)
        return n;
    int a = 0, b = 1;
    for (int i = 2; i <= n; ++i) {
        int next = a + b;
        a = b;
        b = next;
    }
    return b;
}

int fib(int n)
{
    // Memoization table for the first 1000 values to avoid exponential time
    static std::vector<int> memo(1000, -1);

    // Return cached result if available
    if (memo[n] != -1)
        return memo[n];

    // Base case: F(0) = 0, F(1) = 1
    if (n <= 1)
        return n;

    // Recursive call with memoization
    memo[n] = fib(n - 1) + fib(n - 2);
    return memo[n];
}

int paths(int rows, int cols)
{
    // Base case: a single‑row or single‑column grid has exactly one path.
    if (rows == 1 || cols == 1)
