int paths(int rows, int cols)
{
    // Memoization table: dp[i][j] stores the number of paths from (1,1) to (i,j)
    std::vector<std::vector<int>> dp(rows + 1, std::vector<int>(cols + 1, 0));

    // Base case: only one way to reach the top‑left corner
    dp[1][1] = 1;

    // Fill the table using the recurrence dp[i][j] = dp[i‑1][j] + dp[i][j‑1]
    for (int i = 1; i <= rows; ++i) {
        for (int j = 1; j <= cols; ++j) {
            dp[i][j] = dp[i-1][j] + dp[i][j-1];
        }
    }

    // The answer is the number of paths from (1,1) to (rows,cols)
    return dp[rows][cols];
}

int ways(int coins[], int count, int amount)
{
    // Base case: exact amount achieved.
    if (amount == 0)
        return 1;

    // No more coins or insufficient remaining amount.
    if (amount < 0 || count == 0)
        return 0;

    // Recursive case: either exclude the current coin or include it.
    return ways(coins, count - 1, amount) + ways(coins, count, amount - coins[count - 1]);
}

