int ways(int coins[], int count, int amount)
{
    // Guard against null pointer or invalid count.
    if (!coins || count <= 0) return 0;

    // Memoization table: dp[i][j] stores the number of ways to make j with the first i coins.
    std::vector<std::vector<int>> dp(count + 1, std::vector<int>(amount + 1, 0));

    // Fill the table using the original recursive logic.
    for (int i = 1; i <= count; ++i) {
        for (int j = 0; j <= amount; ++j) {
            if (j == 0) {
                dp[i][j] = 1; // Only one way to make amount 0.
            } else if (j < coins[i - 1]) {
                dp[i][j] = dp[i - 1][j]; // Cannot use coin i.
            } else {
                dp[i][j] = dp[i - 1][j] + dp[i][j - coins[i - 1]]; // Use coin i or skip it.
            }
        }
    }

    return dp[count][amount];
}
